/* Thumbnail Index — Hover Title */

.thumbnail {
    position: relative;
}

/* Project title */
.thumbnail .title {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;

    opacity: 0;
    z-index: 2;

    color: white;
    text-align: center;

    transition: opacity 0.25s ease;
}

/* Show title on hover */
.thumbnail:hover .title {
    opacity: 1;
}

/* Image transition */
.thumbnail img {
    transition: filter 0.25s ease;
}

/* Slightly darken image */
.thumbnail:hover img {
    filter: brightness(70%);
}

